/* Test 64: the integer to float conversion routines, __floatdisf,
   __floatundisf, __floattisf and __floatuntisf. Each row is a 128-bit value
   and the four floats it should give: its low half read as signed and as
   unsigned, and the whole of it read both ways. The expected bit patterns are
   rounded once, to nearest with ties to even, so a routine that rounds twice
   or drops a sticky bit is caught. Returns 0xFFFF when every row agrees,
   otherwise the one-based number of the first row that did not.
   NATIVE-SKIP  expect 0xFFFF */
typedef unsigned short uint16_t;
typedef unsigned long uint32_t;
typedef long long i64;
typedef unsigned long long u64;
typedef __int128 i128;
typedef unsigned __int128 u128;
typedef union { float f; uint32_t u; } f32u;

static uint32_t bits(float f) { f32u x; x.f = f; return x.u; }

struct row {
    u64 lo, hi;
    uint32_t sdi, udi, sti, uti;
};

